"""Shared helpers for auditing recorded runs of the harness tree."""

import json
import os
import re
import sys

sys.path.insert(0, "/workspace/harness/solver")

RUNS = sorted(
    d for d in os.listdir("/workspace/runs")
    if os.path.isdir(f"/workspace/runs/{d}") and re.fullmatch(r"[0-9a-f]{40}", d)
)

TASKS = ("USPTO", "Symptom2Disease", "LawBench")

ANSWER_PATTERN = re.compile(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"')


def text_of(content) -> str:
    if isinstance(content, str):
        return content
    return "".join(
        block if isinstance(block, str) else block.get("text", "")
        for block in (content or [])
    )


def rows(run):
    return [json.loads(line) for line in open(f"/workspace/runs/{run}/results/samples.jsonl")]


def conversation(run, task, index, sample):
    path = f"/workspace/runs/{run}/{task}/conversations/{index:04d}/sample-{sample}.json"
    if not os.path.exists(path):
        return None
    return json.load(open(path))


def agent_answer(conv):
    """The answer the agent's own last message carried, before any grounding."""
    for message in reversed(conv["messages"]):
        if message.get("role") != "assistant":
            continue
        text = text_of(message.get("content"))
        match = ANSWER_PATTERN.search(text)
        if match:
            return match.group(1), text
    return None, ""


def adjudicator_reply(conv):
    """The adjudicator's own (from, to) proposal pairs, by replaying its recorded reply."""
    for side in conv.get("side_calls") or []:
        for message in side:
            text = text_of(message.get("content"))
            if message.get("role") == "user" and "## The answer the agent gave" in text:
                prompt = text
            elif message.get("role") == "assistant":
                return json.loads(json.dumps(prompt_to_pairs(text)))
    return []


def prompt_to_pairs(response: str):
    for candidate in _json_candidates(response):
        try:
            data = json.loads(candidate)
        except Exception:
            continue
        if not isinstance(data, dict):
            continue
        items = data.get("rewrites")
        if not isinstance(items, list):
            continue
        return [
            (item["from"], item["to"])
            for item in items
            if isinstance(item, dict)
            and isinstance(item.get("from"), str)
            and isinstance(item.get("to"), str)
        ]
    return []


def _json_candidates(text):
    yield text
    for match in re.finditer(r"```(?:json)?\s*([\s\S]*?)\s*```", text):
        yield match.group(1)
    match = re.search(r"\{[\s\S]*\}", text)
    if match:
        yield match.group(0)


def adjudicated_answer(conv):
    """The value the adjudicator was shown and the pairs it proposed, when it ran."""
    shown = None
    for side in conv.get("side_calls") or []:
        reply = None
        for message in side:
            text = text_of(message.get("content"))
            if message.get("role") == "user" and "## The answer the agent gave" in text:
                match = re.search(
                    r"## The answer the agent gave\s*\n\s*(.*?)\n\s*## How the training memory",
                    text, re.S,
                )
                shown = match.group(1).strip() if match else None
            elif message.get("role") == "assistant":
                reply = text
        if shown is not None:
            return shown, prompt_to_pairs(reply or "")
    return None, []

