"""Measure what the grounding path does to the agent's own answer, run by run."""

import sys

sys.path.insert(0, "/tmp/r12")
sys.path.insert(0, "/workspace")

import collections
import json

import lib
from benchmark.data.evaluators import get_evaluator


def raw_result(task, raw, target):
    if raw is None:
        return None
    result = get_evaluator(task)(raw, target)
    return result["was_correct"] if isinstance(result, dict) else bool(result)


def main():
    for run in lib.RUNS:
        totals = collections.Counter()
        flips = collections.Counter()
        per_task = collections.defaultdict(collections.Counter)
        missing = 0
        for r in lib.rows(run):
            conv = lib.conversation(run, r["task"], r["example_index"], r["sample_index"])
            if conv is None:
                continue
            raw, _ = lib.agent_answer(conv)
            if raw is None:
                missing += 1
                continue
            before = raw_result(r["task"], raw, r["target"])
            after = bool(r["was_correct"])
            if raw == r["prediction"]:
                key = "unchanged"
            elif before and not after:
                key = "broke"
            elif not before and after:
                key = "fixed"
            else:
                key = "neutral"
            totals[key] += 1
            per_task[r["task"]][key] += 1
            if key in ("broke", "fixed"):
                flips[key].append((r["task"], r["example_index"], r["sample_index"], raw, r["prediction"], r["target"]))
        print(f"== {run[:8]}  no-answer-field={missing}  {dict(totals)}")
        for task in lib.TASKS:
            if per_task[task]:
                print(f"   {task:17s} {dict(per_task[task])}")
        for key in ("broke", "fixed"):
            for row in flips[key][:6]:
                print(f"   {key}: {row[0]} ex{row[1]} s{row[2]} {row[3]!r} -> {row[4]!r} (target {row[5]!r})")


if __name__ == "__main__":
    main()

