"""Classify each recorded sample by the path that produced its answer."""

import sys

sys.path.insert(0, "/tmp/r12")
sys.path.insert(0, "/workspace")

import collections

import lib
from benchmark.data.evaluators import get_evaluator


def classify(conv):
    """Which of the three answer paths produced this sample's answer."""
    restate = recover = adjudicate = False
    for side in conv.get("side_calls") or []:
        for message in side:
            if message.get("role") != "user":
                continue
            text = lib.text_of(message.get("content"))
            if "does not carry the answer in the JSON object" in text:
                restate = True
            elif "could not finish the problem" in text:
                recover = True
            elif "## How the training memory spells answers" in text:
                adjudicate = True
    if recover:
        return "recovered" + ("+adj" if adjudicate else "")
    if restate:
        return "restated" + ("+adj" if adjudicate else "")
    return "direct"


def main():
    for run in lib.RUNS:
        stats = collections.defaultdict(collections.Counter)
        for r in lib.rows(run):
            conv = lib.conversation(run, r["task"], r["example_index"], r["sample_index"])
            if conv is None:
                continue
            key = classify(conv)
            stats[r["task"]][key + (":right" if r["was_correct"] else ":wrong")] += 1
            stats["ALL"][key] += 1
            stats["ALL"][key + (":right" if r["was_correct"] else ":wrong")] += 1
        print(f"== {run[:8]} ALL {dict(stats['ALL'])}")
        for task in lib.TASKS:
            if stats[task]:
                print(f"   {task:17s} {dict(stats[task])}")


if __name__ == "__main__":
    main()

