import sys; sys.path.insert(0,'/tmp/r12'); sys.path.insert(0,'/workspace')
import lib, json, re, collections
run='5ac00dbbca9c8f149a9d95d995ea5b744a01f789'
def parse(t):
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", t)
    if m: t=m.group(1)
    t=re.sub(r"<eoa>.*","",t).strip()
    for sep in [";","；",",","，","、"]:
        if sep in t: return {p.strip() for p in t.split(sep) if p.strip()}
    return {t} if t else set()
for task in ('LawBench','Symptom2Disease','USPTO'):
    mem=json.load(open(f'/workspace/runs/{run}/{task}/memory.json'))['examples']
    stored={str(e['target']).strip() for e in mem}
    if task=='LawBench': stored|= {p for s in stored for p in parse(s)}
    rows=[r for r in lib.rows(run) if r['task']==task]
    exact=allparts=0
    for r in rows:
        t=r['target']
        if task=='LawBench':
            p=parse(t)
            if t.strip() in stored: exact+=1
            if p<=stored: allparts+=1
        elif task=='Symptom2Disease':
            if t.strip() in stored: exact+=1; allparts+=1
        else:
            if t.strip() in stored: exact+=1
            if {x for x in t.split('.')} <= {x for s in stored for x in s.split('.')}: allparts+=1
    print(f'{task}: val targets present as a stored answer {exact}/{len(rows)}; all pieces stored {allparts}/{len(rows)}')
EOF

