"""Would a deterministic 'complete the answer to a stored answer that contains it' rule pay?

Measured on the recorded raw answers of every run: for each sample whose answer's
charge set is a strict subset of a stored answer's charge set, is the completing
stored answer the one the sample needs?
"""

import sys

sys.path.insert(0, "/tmp/r12")
sys.path.insert(0, "/workspace")
sys.path.insert(0, "/workspace/harness/solver")

import collections
import json
import re

import lib
from benchmark.data.evaluators import get_evaluator


def parse(text):
    match = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if match:
        text = match.group(1)
    text = re.sub(r"<eoa>.*", "", text).strip()
    for separator in [";", "；", ",", "，", "、"]:
        if separator in text:
            return frozenset(part.strip() for part in text.split(separator) if part.strip())
    return frozenset([text]) if text else frozenset()


def ok(task, prediction, target):
    result = get_evaluator(task)(prediction, target)
    return result["was_correct"] if isinstance(result, dict) else bool(result)


def evidence_answers(conv):
    answers = set()
    for message in conv.get("messages") or []:
        if message.get("role") != "tool":
            continue
        text = lib.text_of(message.get("content"))
        answers |= {line[3:].strip() for line in text.splitlines() if line.startswith("A: ")}
    return answers


def main():
    stats = collections.Counter()
    examples = collections.defaultdict(list)
    for run in lib.RUNS:
        for r in lib.rows(run):
            if r["task"] != "LawBench":
                continue
            conv = lib.conversation(run, "LawBench", r["example_index"], r["sample_index"])
            if conv is None:
                continue
            raw, _ = lib.agent_answer(conv)
            if raw is None:
                shown, _ = lib.adjudicated_answer(conv)
                raw = shown
            if not raw:
                continue
            pred = parse(raw)
            target = parse(r["target"])
            delivered = evidence_answers(conv)
            options = [parse(a) for a in delivered if len(parse(a)) > len(pred)]
            options = [o for o in options if pred < o]
            unique = {tuple(sorted(o)) for o in options}
            stats["samples"] += 1
            stats["has candidate"] += bool(unique)
            stats["unique candidate"] += len(unique) == 1
            if len(unique) != 1:
                continue
            completed = ";".join(next(iter(unique)))
            fixed = ok("LawBench", completed, r["target"])
            already = ok("LawBench", raw, r["target"])
            stats["fires"] += 1
            stats[f"fire_{'right' if already else 'wrong'}"] += 1
            if fixed and not already:
                stats["fixes"] += 1
            elif already and not fixed:
                stats["breaks"] += 1
            examples["fix" if (fixed and not already) else "break" if (already and not fixed) else "same"].append(
                (run[:7], r["example_index"], r["sample_index"], sorted(pred), sorted(target), sorted(unique)[0])
            )
    print(json.dumps(dict(stats), indent=1))
    for key, rows in examples.items():
        print(f"-- {key}: {len(rows)}")
        for row in rows[:8]:
            print("   ", row)


if __name__ == "__main__":
    main()

