"""Measure: does the agent's own message already carry the answer in the task's
own markup, and is that answer better than the one the restatement returned?

The markup is derived from the problem text itself: the span of the problem that
wraps a value the frozen memory stores as an answer/answer part is the shape the
task asks its answer to take.
"""

import sys

sys.path.insert(0, "/tmp/r12")
sys.path.insert(0, "/workspace")
sys.path.insert(0, "/workspace/harness/solver")

import collections
import re

import lib
from benchmark.data.evaluators import get_evaluator

import answer_space as A


def ok(task, prediction, target):
    if not prediction:
        return False
    result = get_evaluator(task)(prediction, target)
    return result["was_correct"] if isinstance(result, dict) else bool(result)


def markups(problem, values):
    """The (prefix, suffix) pairs that wrap a stored value inside the problem."""
    found = set()
    for value in values:
        start = problem.find(value)
        while start != -1:
            prefix_start = start
            while prefix_start > 0 and problem[prefix_start - 1] in "[（(<【":
                prefix_start -= 1
            end = start + len(value)
            suffix_end = end
            while suffix_end < len(problem) and problem[suffix_end] in "])>）】":
                suffix_end += 1
            prefix, suffix = problem[prefix_start:start], problem[end:suffix_end]
            if prefix and suffix and suffix != ">":
                found.add((prefix, suffix))
            start = problem.find(value, start + 1)
    # keep the longest (most specific) prefixes/suffixes first
    return sorted(found, key=lambda ps: (-len(ps[0]), -len(ps[1])))


def marked_answer(message, markups):
    """The last answer the message writes inside the task's own markup."""
    best = None
    for prefix, suffix in markups:
        pattern = re.escape(prefix) + r"(.*?)" + re.escape(suffix)
        for match in re.finditer(pattern, message, re.S):
            body = match.group(1).strip()
            if body and (best is None or match.start() >= best[0]):
                best = (match.start(), prefix + body + suffix)
    return best[1] if best else None


def main():
    stats = collections.Counter()
    for run in lib.RUNS:
        for r in lib.rows(run):
            conv = lib.conversation(run, r["task"], r["example_index"], r["sample_index"])
            if conv is None:
                continue
            if lib.agent_answer(conv)[0] is not None:
                continue                                    # the message carried a JSON field
            restated = any(
                "does not carry the answer in the JSON object" in lib.text_of(m.get("content"))
                for side in (conv.get("side_calls") or []) for m in side if m.get("role") == "user"
            )
            recovered = any(
                "could not finish the problem" in lib.text_of(m.get("content"))
                for side in (conv.get("side_calls") or []) for m in side if m.get("role") == "user"
            )
            if not restated or recovered:
                continue
            message = lib.text_of(conv["messages"][-1].get("content"))
            if not message:
                continue
            problem = lib.problem_of(conv)
            values = A.stored_values(f"/workspace/runs/{run}/{r['task']}/memory.json")
            shapes = markups(problem, values)
            if not shapes:
                stats[(r["task"], "no markup shape in the problem")] += 1
                continue
            carried = marked_answer(message, shapes)
            stats[(r["task"], "message carries a marked answer" if carried else "message carries none")] += 1
            if not carried:
                continue
            stats[(r["task"], "carried == restated" if carried == r["prediction"] else "carried != restated")] += 1
            restated_ok = ok(r["task"], r["prediction"], r["target"])
            carried_ok = ok(r["task"], carried, r["target"])
            if carried_ok and not restated_ok:
                stats[(r["task"], "carried right / restated wrong")] += 1
            elif restated_ok and not carried_ok:
                stats[(r["task"], "restated right / carried wrong")] += 1
            else:
                stats[(r["task"], "both same verdict")] += 1
    for key in sorted(stats, key=str):
        print(f"{stats[key]:5d}  {key}")


if __name__ == "__main__":
    main()

