"""Probe an in-context answer resolution against the shipped restatement.

The shipped resolution re-asks a fresh single-turn call carrying only the agent's
last message.  This probe instead continues the agent's own conversation -- the
one that holds the evidence it retrieved -- with one instruction to state the
answer in the field the runner reads, and measures what the continuation would
return on the samples where the shipped path restated.
"""

import sys

sys.path.insert(0, "/tmp/r12")
sys.path.insert(0, "/workspace")

import concurrent.futures as futures
import json
import os
import re

from openai import OpenAI

import lib
from benchmark.data.evaluators import get_evaluator

CLIENT = OpenAI(
    base_url="https://dashscope.aliyuncs.com/compatible-mode/v1",
    api_key=os.environ["BAILIAN_API_KEY"],
    timeout=300, max_retries=0,
)

INSTRUCTION = (
    "Your final message must be a single JSON object with exactly two string fields, "
    '"reasoning" and "final_answer". Put the answer itself inside "final_answer", keeping '
    "any markup the problem's own instructions ask the answer to carry. Reply with only the "
    "JSON object."
)


def normalize(messages):
    """The recorded messages, in the shape the provider accepts."""
    out = []
    for message in messages:
        role = message.get("role")
        content = message.get("content")
        if isinstance(content, list):
            content = "".join(
                block.get("text", "") if isinstance(block, dict) else str(block)
                for block in content
            )
        if content is None:
            content = ""
        item = {"role": role, "content": content}
        if message.get("tool_calls"):
            item["tool_calls"] = message["tool_calls"]
        if message.get("tool_call_id"):
            item["tool_call_id"] = message["tool_call_id"]
        out.append(item)
    return out


def field_of(text):
    for field in ("final_answer", "answer"):
        match = re.search(r'"%s"\s*:\s*"((?:[^"\\]|\\.)*)"' % field, text or "")
        if match:
            value = match.group(1)
            try:
                value = json.loads('"' + value + '"')
            except Exception:                                       # noqa: BLE001
                pass
            return value
    return None


def ok(task, prediction, target):
    if not prediction:
        return False
    result = get_evaluator(task)(prediction, target)
    return result["was_correct"] if isinstance(result, dict) else bool(result)


def one(run, row):
