        return None
    messages = normalize(conv["messages"])
    messages = [m for m in messages if m["role"] in {"system", "user", "assistant", "tool"}]
    try:
        response = CLIENT.chat.completions.create(
            model="qwen3.7-flash",
            messages=messages + [{"role": "user", "content": INSTRUCTION}],
            temperature=0.0, max_tokens=8192, extra_body={"enable_thinking": True},
        )
        reply = response.choices[0].message.content or ""
    except Exception as error:                                      # noqa: BLE001
        reply = f"__error__ {error}"
    return {"key": [run[:7], row["task"], row["example_index"], row["sample_index"]],
            "reply": reply, "parsed": field_of(reply),
            "restated": row["prediction"], "target": row["target"],
            "restated_right": bool(row["was_correct"]),
            "prose": lib.text_of(conv["messages"][-1].get("content"))}


def main():
    out = sys.argv[1]
    jobs = []
    for run in lib.RUNS:
        for row in lib.rows(run):
            jobs.append((run, row))
    results = []
    with futures.ThreadPoolExecutor(max_workers=16) as pool:
