        if parsed is None:
            stats["unparsed"] += 1
            continue
        if parsed != result["restated"]:
            stats["changed"] += 1
        after = ok("Symptom2Disease" if result["key"][1] == "Symptom2Disease" else result["key"][1],
                   parsed, result["target"])
        if after == result["restated_right"]:
            stats["same"] += 1
        elif after:
            stats["fix"] += 1
            flips.append(("fix", result["key"], result["restated"], parsed, result["target"]))
        else:
            stats["break"] += 1
            flips.append(("break", result["key"], result["restated"], parsed, result["target"]))
    print(json.dumps(stats, ensure_ascii=False))
    for flip in flips:
