sys.path.insert(0, "/workspace")
sys.path.insert(0, "/workspace/harness/solver")

import collections
import json
import statistics

import lib
from benchmark.data.evaluators import get_evaluator

import resolution

CANDIDATE = "83ed278ac33df92c592b4c5f3d6a1ca0170aab56"
PARENT = "b960408ce5adbf50e843035f4c3dcb5601cc2992"


def rows(run):
    return [json.loads(line) for line in open(f"/workspace/runs/{run}/results/samples.jsonl")]


def fired(conv):
    """True when the run was continued in context to state the answer."""
    for message in conv.get("messages") or []:
        if message.get("role") != "user":
            continue
        if lib.text_of(message.get("content")).strip() == resolution.CONTINUE.strip():
            return True
    return False


def restated(conv):
    return any(
        "does not carry the answer in the JSON object" in lib.text_of(m.get("content"))
        for side in (conv.get("side_calls") or []) for m in side if m.get("role") == "user"
    )


def recovered(conv):
    return any(
        "could not finish the problem" in lib.text_of(m.get("content"))
        for side in (conv.get("side_calls") or []) for m in side if m.get("role") == "user"
    )


def correct(task, prediction, target):
    if not prediction:
        return False
    result = get_evaluator(task)(prediction, target)
    return result["was_correct"] if isinstance(result, dict) else bool(result)


def main():
    stats = collections.Counter()
    flips = collections.defaultdict(list)
    parent_rows = {(r["task"], r["example_index"], r["sample_index"]): r for r in rows(PARENT)}
    for row in rows(CANDIDATE):
        conv = lib.conversation(CANDIDATE, row["task"], row["example_index"], row["sample_index"])
        key = (row["task"], row["example_index"], row["sample_index"])
        stats[(row["task"], "samples")] += 1
        if fired(conv):
            stats[(row["task"], "in-run resolve fired")] += 1
            stats[(row["task"], "in-run fired: right" if row["was_correct"] else "in-run fired: wrong")] += 1
        if restated(conv):
            stats[(row["task"], "fallback restatement fired")] += 1
        if recovered(conv):
            stats[(row["task"], "recovery fired")] += 1
        before = parent_rows.get(key)
        if before is None:
            continue
        if before["prediction"] != row["prediction"]:
            moved = ("wrong->right" if row["was_correct"] and not before["was_correct"]
                     else "right->wrong" if before["was_correct"] and not row["was_correct"]
                     else "wrong->wrong" if not before["was_correct"] else "right->right")
            stats[(row["task"], f"changed: {moved}")] += 1
            flips[moved].append((key, before["prediction"], row["prediction"], row["target"],
                                 before["was_correct"], row["was_correct"], fired(conv)))
    for task in lib.TASKS:
        for label in ("samples", "in-run resolve fired", "in-run fired: right", "in-run fired: wrong",
                      "fallback restatement fired", "recovery fired",
                      "changed: wrong->right", "changed: right->wrong",
                      "changed: wrong->wrong", "changed: right->right"):
            if stats[(task, label)]:
                print(f"{task:17s} {label:32s} {stats[(task, label)]}")
    print()
    for key in ("wrong->right", "right->wrong"):
        print(f"-- {key}: {len(flips[key])}")
        for flip in flips[key][:14]:
            print("   ", flip)
    print()
    for run, name in ((CANDIDATE, "candidate"), (PARENT, "parent")):
        data = rows(run)
        print(name, "elapsed median %.1f" % statistics.median(r["elapsed_seconds"] for r in data),
              "calls median", statistics.median(r["usage"]["model_calls"] for r in data),
              "in-tokens", sum(r["usage"]["input_tokens"] for r in data),
              "out-tokens", sum(r["usage"]["output_tokens"] for r in data),
              "ctx mean %.0f" % statistics.mean(r["memory_context_chars"] for r in data))


if __name__ == "__main__":
    main()

